"""Markdown tables for REPORT.md files."""
from __future__ import annotations

import numpy as np

SYNTHETIC_BANNER = (
    "> **SYNTHETIC DATA. This is a software check only.** The fields were generated by "
    "`tests/synthetic.py` from hand-written spectra. Nothing below says anything about how the "
    "model does on real fields.\n"
)

TABLE_METRICS = [("precision", "precision"), ("recall", "recall"), ("fpr", "FPR"),
                 ("f1", "F1"), ("balanced_accuracy", "bal. acc."), ("roc_auc", "ROC-AUC"),
                 ("pr_auc", "PR-AUC")]


def fmt(v, digits=3):
    if v is None:
        return "–"
    try:
        v = float(v)
    except (TypeError, ValueError):
        return str(v)
    if not np.isfinite(v):
        return "n/a"
    return f"{v:.{digits}f}"


def fmt_ci(m, key, digits=2):
    v = fmt(m.get(key), digits + 1)
    ci = m.get("ci95", {}).get(key)
    if ci and all(c is not None and np.isfinite(c) for c in ci):
        return f"{v} [{ci[0]:.{digits}f}, {ci[1]:.{digits}f}]"
    return v


def metrics_table(models, subset="all", order=None, label_col="model", extra_cols=()):
    """models: name -> summary record (with 'all' / 'confident' subsets)."""
    order = order or list(models)
    head = [label_col, "n (silage)"] + [h for _, h in TABLE_METRICS] + [h for h, _ in extra_cols]
    lines = ["| " + " | ".join(head) + " |", "|" + "---|" * len(head)]
    for name in order:
        if name not in models:
            continue
        m = models[name][subset] if subset else models[name]
        cells = [name, f"{m['n']} ({m['n_silage']})"]
        cells += [fmt_ci(m, k) for k, _ in TABLE_METRICS]
        cells += [fmt(fn(m)) for _, fn in extra_cols]
        lines.append("| " + " | ".join(cells) + " |")
    return "\n".join(lines)


def confusion_line(m):
    c = m["confusion"]
    return f"TP {c['tp']}, FP {c['fp']}, FN {c['fn']}, TN {c['tn']}"


def kv_table(rows, headers):
    lines = ["| " + " | ".join(headers) + " |", "|" + "---|" * len(headers)]
    for r in rows:
        lines.append("| " + " | ".join(fmt(x) if isinstance(x, float) else str(x) for x in r) + " |")
    return "\n".join(lines)
